static void dm_DsLTporozhdenieu2ePotreblyaemyj_release(dm_DsLTporozhdenieu2ePotreblyaemyj *d) { if (d) dan_hdr_release(&d->h, dm_DsLTporozhdenieu2ePotreblyaemyj_destroy); }
